@pytest.mark.asyncio

async def test_ollama_chat() -> None:
    """Ollama provider sends the chat to /api/chat and maps the native reply, including token counts and finish reason."""
    client = create_client(api_key="test-key", base_url=os.environ["MOCK_SERVER_URL"] + "/fixtures/ollama_chat")
    req = ChatCompletionRequest.from_json("{\"extra_body\":{\"num_ctx\":512,\"repeat_penalty\":1.1,\"top_k\":5},\"messages\":[{\"content\":\"Hello\",\"role\":\"user\"}],\"model\":\"ollama/qwen2:0.5b\"}")

    result = await client.chat(req)
    assert len(result.choices) == 1
    assert result.choices[0].message.content is not None
    assert result.choices[0].message.content.text is not None
    assert result.choices[0].message.content.text.lower() == "Hello! How can I help you today?".lower()
    assert _alef_e2e_text(result.choices[0].finish_reason).lower() == "stop".lower()
    assert result.model == "qwen2:0.5b"
    assert (result.usage.prompt_tokens if result.usage else None) == 5
    assert (result.usage.completion_tokens if result.usage else None) == 8
    assert (result.usage.total_tokens if result.usage else None) == 13


